    });
  };

  return (
    <View>
      {isSyncing && <SyncIndicator count={pendingCount} />}
      <FlatList
        data={images}
        renderItem={({ item }) => (
          <ImageItem 
            thumbnail={item.thumbnailPath}
            status={item.status}
          />
